#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/drotg.h"
#include "stdlib/math/base/special/abs2.h"
#include "stdlib/math/base/special/abs.h"
#include "stdlib/math/base/special/copysign.h"
#include "stdlib/math/base/special/sqrt.h"
#include <float.h>
#include <math.h>

/**
* Constructs a Givens plane rotation using alternative indexing semantics.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
* @param offsetOut  starting index for `Out`
*/
void API_SUFFIX( c_drotg_assign )( const double a, const double b, double *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	double anorm;
	double bnorm;
	double scale;
	double sigma;
	double r;
	double c;
	double s;
	double z;
	double safmin;
	double safmax;

	// Compute safe scaling constants (matching the reference BLAS implementation)
	safmin = DBL_MIN * ( 1.0 / DBL_EPSILON );
	safmax = DBL_MAX * DBL_EPSILON;

	anorm = stdlib_base_abs( a );
	bnorm = stdlib_base_abs( b );

	if ( bnorm == 0.0 ) {
		c = 1.0;
		s = 0.0;
		r = a;
		z = 0.0;
	} else if ( anorm == 0.0 ) {
		c = 0.0;
		s = 1.0;
		r = b;
		z = 1.0;
	} else {
		scale = fmin( safmax, fmax( safmin, fmax( anorm, bnorm ) ) );
		if ( anorm > bnorm ) {
			sigma = stdlib_base_copysign( 1.0, a );
		} else {
			sigma = stdlib_base_copysign( 1.0, b );
		}
		r = sigma * ( scale * stdlib_base_sqrt( stdlib_base_abs2( a / scale ) + stdlib_base_abs2( b / scale ) ) );
		c = a / r;
		s = b / r;
		if ( anorm > bnorm ) {
			z = s;
		} else if ( c != 0.0 ) {
			z = 1.0 / c;
		} else {
			z = 1.0;
		}
	}
	Out[ offsetOut ] = r;
	Out[ offsetOut + strideOut ] = z;
	Out[ offsetOut + ( 2 * strideOut ) ] = c;
	Out[ offsetOut + ( 3 * strideOut ) ] = s;
	return;
}
